def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    answers=inputs.get('semantic_answers',[])
    all_ids=[]
    unit_text={}
    for unit in spans:
        uid=unit.get('id')
        if isinstance(uid,int):
            all_ids.append(uid)
            unit_text[uid]=unit.get('text','')
    statements=[]
    statement_keys=set()
    unresolved=[]
    audits={}
    disclosure_count=0
    disposal_count=0
    retention_count=0
    for answer in answers:
        if not isinstance(answer,dict):
            continue
        qid=answer.get('id')
        choice=answer.get('choice')
        if not isinstance(qid,str):
            continue
        if choice=='unknown' or choice is None:
            unresolved.append('Unresolved semantic reading: '+qid)
            continue
        support=[]
        quotes=[]
        evidence=answer.get('evidence',[])
        if isinstance(evidence,list):
            for item in evidence:
                if isinstance(item,dict):
                    uid=item.get('unit_id')
                    quote=item.get('quote')
                    if isinstance(uid,int) and uid in unit_text and uid not in support:
                        support.append(uid)
                    if isinstance(quote,str) and quote:
                        quotes.append(quote)
        selected=answer.get('selected_evidence_unit_ids',[])
        if isinstance(selected,list):
            for uid in selected:
                if isinstance(uid,int) and uid in unit_text and uid not in support:
                    support.append(uid)
        if quotes:
            qualifier=quotes[-1]
        elif support:
            qualifier=unit_text.get(support[-1],'')
        else:
            qualifier=''
        terms=[]
        ci=['confidential_information']
        receiver=['receiving_party']
        discloser=['disclosing_party']
        condition=['and_condition',['need_to_know',qualifier],['confidentiality_bound',qualifier]]
        if qid.startswith('disclosure:'):
            if not support:
                unresolved.append('Disclosure choice lacks grounded evidence: '+qid)
                continue
            if choice=='affiliate_personnel_permission':
                affiliate=['affiliates_of',receiver]
                recipients=['participant_union',['employees_of',affiliate],['participant_union',['directors_of',affiliate],['officers_of',affiliate]]]
                terms.append(['permission',receiver,['disclose',ci,recipients],condition])
                disclosure_count+=1
            elif choice=='internal_employee_officer_director_permission':
                recipients=['participant_union',['employees_of',receiver],['participant_union',['directors_of',receiver],['officers_of',receiver]]]
                terms.append(['permission',receiver,['disclose',ci,recipients],condition])
                disclosure_count+=1
            elif choice=='internal_employee_director_contractor_exception_to_third_party_ban':
                recipients=['participant_union',['employees_of',receiver],['participant_union',['directors_of',receiver],['independent_contractors_of',receiver]]]
                permitted=['permission',receiver,['disclose',ci,recipients],condition]
                terms.append(permitted)
                terms.append(['prohibition',receiver,['disclose',ci,['third_parties']],['no_condition'],['exception_set',['permission_exception',permitted]]])
                disclosure_count+=1
            elif choice=='general_third_party_prohibition':
                terms.append(['prohibition',receiver,['disclose',ci,['third_parties']],['no_condition'],['no_exceptions']])
            elif choice=='other_relevant_clause':
                unresolved.append('Unsupported relevant disclosure frame: '+qid)
            elif choice!='not_relevant_or_nonoperative':
                unresolved.append('Unrecognized disclosure choice: '+qid)
        elif qid.startswith('disposal:'):
            if not support:
                unresolved.append('Disposal choice lacks grounded evidence: '+qid)
                continue
            bundle=['information_bundle',ci,['copies_of',ci]]
            if choice=='agreement_termination_or_request_return_or_authorized_destroy_with_archival_copy':
                returned=['return_to',bundle,discloser]
                destroyed=['destroy',bundle]
                action=['source_authorized_action_alternative',returned,destroyed,qualifier]
                trigger=['trigger_alternative',['agreement_termination'],['request_by',discloser]]
                retained=['retention_exception',receiver,['copies_of',ci],['retention_condition',qualifier]]
                terms.append(['disposal_obligation',receiver,action,trigger,['exception_set',retained]])
                disposal_count+=1
            elif choice=='purpose_completion_or_request_return_all_no_retention':
                action=['return_to',bundle,discloser]
                trigger=['trigger_alternative',['purpose_completion'],['request_by',discloser]]
                terms.append(['disposal_obligation',receiver,action,trigger,['no_exceptions']])
                disposal_count+=1
            elif choice=='other_relevant_clause':
                unresolved.append('Unsupported relevant disposal frame: '+qid)
            elif choice!='not_relevant_or_nonoperative':
                unresolved.append('Unrecognized disposal choice: '+qid)
        elif qid.startswith('retention:'):
            if not support:
                unresolved.append('Retention choice lacks grounded evidence: '+qid)
                continue
            if choice=='archival_copy_permission':
                terms.append(['retention_permission',receiver,['copies_of',ci],['after_disposal'],['retention_condition',qualifier]])
                retention_count+=1
            elif choice=='explicit_retention_prohibition':
                terms.append(['retention_prohibition',receiver,ci,['after_disposal']])
                retention_count+=1
            elif choice=='other_explicit_retention_effect':
                unresolved.append('Unsupported explicit retention frame: '+qid)
            elif choice!='no_retention_effect_in_this_unit':
                unresolved.append('Unrecognized retention choice: '+qid)
        elif qid=='audit:disclosure':
            audits['disclosure']=[choice,list(support)]
        elif qid=='audit:disposal':
            audits['disposal']=[choice,list(support)]
        elif qid=='audit:retention':
            audits['retention']=[choice,list(support)]
        for term in terms:
            key=repr(term)+'|'+repr(sorted(support))
            if key not in statement_keys:
                statement_keys.add(key)
                statements.append({'term':term,'support_ids':sorted(support)})
    audit_specs=[('disclosure','no_operative_internal_or_service_permission','complete_source_no_disclosure_permission'),('disposal','no_operative_disposal_obligation','complete_source_no_disposal_obligation'),('retention','no_explicit_post_disposal_retention_effect','complete_source_no_retention_effect')]
    for category,absence_choice,constructor in audit_specs:
        if category not in audits:
            unresolved.append('Missing complete-source '+category+' audit')
            continue
        choice,support=audits[category]
        if choice==absence_choice:
            if set(support)!=set(all_ids) or not all_ids:
                unresolved.append('Incomplete evidence for complete-source '+category+' absence')
            else:
                term=[constructor]
                key=repr(term)+'|'+repr(sorted(all_ids))
                if key not in statement_keys:
                    statement_keys.add(key)
                    statements.append({'term':term,'support_ids':sorted(all_ids)})
        elif choice=='category_present':
            if category=='disclosure' and disclosure_count==0:
                unresolved.append('Disclosure audit found a category but no classified permission clause')
            if category=='disposal' and disposal_count==0:
                unresolved.append('Disposal audit found a category but no classified obligation clause')
            if category=='retention' and retention_count==0:
                unresolved.append('Retention audit found a category but no classified effect clause')
        else:
            unresolved.append('Unrecognized complete-source '+category+' audit choice')
    unique_unresolved=[]
    for item in unresolved:
        if item not in unique_unresolved:
            unique_unresolved.append(item)
    return {'statements':statements,'complete':len(unique_unresolved)==0,'unresolved':unique_unresolved}

