def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    answers=inputs.get('semantic_answers',[])
    seen=set()
    for answer in answers:
        if isinstance(answer,dict) and isinstance(answer.get('id'),str):
            seen.add(answer['id'])
    queries=[]
    all_ids=[]
    i=0
    while i<len(spans):
        unit=spans[i]
        uid=unit.get('id')
        text=unit.get('text','')
        if isinstance(uid,int) and isinstance(text,str):
            all_ids.append(uid)
            low=text.lower()
            context=[]
            j=i-3
            if j<0:
                j=0
            while j<=i:
                prior=spans[j]
                if isinstance(prior.get('id'),int):
                    context.append(prior['id'])
                j+=1
            role_hit=('employee' in low or 'director' in low or 'officer' in low or 'contractor' in low or 'consultant' in low or 'agent' in low or 'adviser' in low or 'advisor' in low or 'third part' in low or 'affiliate' in low)
            if ('disclos' in low or 'access' in low) and role_hit:
                qid='disclosure:'+str(uid)
                if qid not in seen:
                    queries.append({'id':qid,'operation':'disclosure_clause','unit_ids':context})
            material_hit=('confidential' in low or 'document' in low or 'material' in low or 'cop' in low)
            if ('return' in low or 'destroy' in low) and material_hit:
                qid='disposal:'+str(uid)
                if qid not in seen:
                    queries.append({'id':qid,'operation':'disposal_clause','unit_ids':context})
            if 'retain' in low or 'retention' in low or 'archiv' in low:
                qid='retention:'+str(uid)
                if qid not in seen:
                    queries.append({'id':qid,'operation':'retention_clause','unit_ids':context})
        i+=1
    audits=[('audit:disclosure','disclosure_permission_audit'),('audit:disposal','disposal_obligation_audit'),('audit:retention','retention_effect_audit')]
    for qid,operation in audits:
        if qid not in seen and all_ids:
            queries.append({'id':qid,'operation':operation,'unit_ids':list(all_ids)})
    return {'queries':queries}
